def passes(self) -> bool:
    """Return whether this day satisfies every score-health requirement."""
    if not _is_finite_real(self.coverage) or not _is_finite_real(self.score_std):
        return False
    if not isinstance(self.unique_score_count, Integral) or isinstance(self.unique_score_count, bool):
        return False
    coverage = float(self.coverage)
    score_std = float(self.score_std)
    return 0.9 <= coverage <= 1.0 and self.unique_score_count >= 10 and (score_std > 1e-06)
